import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './Survey.css'; // 별도로 CSS 작성

export default function Survey() {
  const navigate = useNavigate();

  const [monthlyRent, setMonthlyRent] = useState('');
  const [deposit, setDeposit] = useState('');
  const [maintenanceFee, setMaintenanceFee] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('설문 결과:', { monthlyRent, deposit, maintenanceFee });
    navigate('/chatbot');
  };

  return (
    <div className="survey-page">
      {/* 헤더 */}
      <header className="header">
        <div
          className="logo"
          style={{ cursor: 'pointer' }}
          onClick={() => navigate('/')}
        >
          🏡 살아보고서
        </div>
        <div className="auth-buttons">
          <button onClick={() => navigate('/')}>로그아웃</button>
        </div>
      </header>

      <div className="survey-container">
        <h2>나의 예산을 선택해주세요</h2>
        <p>선택한 위치 정보가 없습니다.</p>

        <form onSubmit={handleSubmit} className="survey-form">
          <div className="survey-question">
            <span>1️⃣ 월세는 어느 정도까지 괜찮으신가요? (만원)</span>
            <div className="survey-options">
              {['30 이하', '30~50', '50~70', '70 이상'].map((option) => (
                <button
                  key={option}
                  type="button"
                  className={`survey-option ${monthlyRent === option ? 'selected' : ''}`}
                  onClick={() => setMonthlyRent(option)}
                >
                  {option}
                </button>
              ))}
            </div>
          </div>

          <div className="survey-question">
            <span>2️⃣ 보증금은 어느 정도까지 괜찮으신가요? (만원)</span>
            <div className="survey-options">
              {['500 이하', '500~1000', '1000~2000', '2000 이상'].map((option) => (
                <button
                  key={option}
                  type="button"
                  className={`survey-option ${deposit === option ? 'selected' : ''}`}
                  onClick={() => setDeposit(option)}
                >
                  {option}
                </button>
              ))}
            </div>
          </div>

          <div className="survey-question">
            <span>3️⃣ 관리비는 어느 정도까지 괜찮으신가요? (만원)</span>
            <div className="survey-options">
              {['5 이하', '5~10', '10 이상'].map((option) => (
                <button
                  key={option}
                  type="button"
                  className={`survey-option ${maintenanceFee === option ? 'selected' : ''}`}
                  onClick={() => setMaintenanceFee(option)}
                >
                  {option}
                </button>
              ))}
            </div>
          </div>

          <button
            type="submit"
            className="survey-submit"
            disabled={!monthlyRent || !deposit || !maintenanceFee}
          >
            다음으로
          </button>
        </form>
      </div>
    </div>
  );
}
